css:
/* Neon Sunset: a striped sun over a perspective grid, with chrome type. Dark only. */
:root {
  --ns-pink: #ff3ea5;
  --ns-orange: #ffb347;
  --ns-violet: #7b2cff;
  --ns-cyan: #3df2ff;
  --ns-chrome: linear-gradient(180deg, #ffffff 0%, #ffd6f0 38%, #ff7ac8 52%, #6d3cff 54%, #c9b8ff 100%);
}

/* The horizon: sun and grid sit low behind the conversation, dimmed for reading. */
[data-t3-part="transcript"] {
  background:
    linear-gradient(180deg, rgb(13 5 29 / 0.94) 0%, rgb(13 5 29 / 0.86) 45%, rgb(13 5 29 / 0.72) 100%),
